// generated by build-games: content/games/<slug>.html -> bu fayl. Əl ilə dəyişmə; node scripts/build-games.mjs işlət.
export default "<!doctype html>\n<html lang=\"az\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width,initial-scale=1,maximum-scale=1,user-scalable=no\">\n<title>Mina axtaran</title>\n<style>\n*{box-sizing:border-box;-webkit-tap-highlight-color:transparent}\nhtml,body{margin:0;min-height:100%;background:radial-gradient(circle at 50% 0,#17224a,#070b18 70%);color:#e8f0ff;font-family:system-ui,\"Segoe UI\",Roboto,Arial,sans-serif;-webkit-user-select:none;user-select:none}\nbody{display:flex;justify-content:center;padding:10px}\n.wrap{width:100%;max-width:460px;text-align:center}\nh1{margin:6px 0 8px;font-size:24px;letter-spacing:.5px}\n.hud{display:flex;justify-content:space-between;gap:8px;margin:6px 0;font-size:15px}\n.hud span{flex:1;background:#ffffff12;border:1px solid #ffffff22;border-radius:10px;padding:6px 8px}\ncanvas{display:block;margin:0 auto;width:100%;height:auto;border-radius:14px;border:2px solid #4cc9f0;background:#0a1128;touch-action:none;box-shadow:0 0 24px #4cc9f044}\nbutton{font:inherit;color:#fff;background:linear-gradient(#3a86ff,#2563eb);border:0;border-radius:12px;padding:10px 16px;cursor:pointer;box-shadow:0 3px 0 #1b3f9a}\nbutton:active{transform:translateY(2px);box-shadow:none}\n.row{display:flex;gap:8px;justify-content:center;margin:10px 0;flex-wrap:wrap}\n.hint{opacity:.7;font-size:13px;margin:6px 0}\n.msg{min-height:24px;font-weight:700;color:#ffd166;margin:6px 0}\n.board{display:grid;grid-template-columns:repeat(9,1fr);gap:3px;margin:10px auto;width:min(94vw,400px);touch-action:manipulation}\n.m{aspect-ratio:1;padding:0;border-radius:6px;background:#3a4a8a;box-shadow:0 2px 0 #1b2650;font-weight:800;font-size:clamp(14px,5vw,22px);display:flex;align-items:center;justify-content:center;color:#fff}\n.m.o{background:#16204a;box-shadow:none}\n.m.x{background:#7f1d1d}\n.n1{color:#4cc9f0}.n2{color:#7ae582}.n3{color:#ff6b6b}.n4{color:#a78bfa}.n5{color:#ff9f43}.n6{color:#2dd4bf}.n7{color:#fff}.n8{color:#94a3b8}\n#mode.on{background:linear-gradient(#ff9f43,#f97316);box-shadow:0 3px 0 #9a4a0a}\n</style>\n</head>\n<body>\n<div class=\"wrap\">\n<h1>💣 Mina axtaran</h1>\n<div class=\"hud\"><span>💣 <b id=\"left\">10</b></span><span>⏱ <b id=\"tm\">0</b></span></div>\n<div class=\"board\" id=\"bd\"></div>\n<div class=\"msg\" id=\"msg\"></div>\n<div class=\"row\"><button id=\"mode\">🚩 Bayraq rejimi: söndürülü</button><button id=\"re\">Yeni oyun</button></div>\n<p class=\"hint\">Aç: toxun / sol klik. Bayraq: uzun basma / sağ klik / bayraq rejimi</p>\n</div>\n<script>\nconst R = 9, C = 9, MINES = 10;\nconst $ = id => document.getElementById(id);\nlet cells, started, over, opened, flags, secs, timer, flagMode = false, lpFired = false;\n\nfunction neighbors(i) {\n  const r = i / C | 0, c = i % C, out = [];\n  for (let dr = -1; dr <= 1; dr++) for (let dc = -1; dc <= 1; dc++) {\n    const nr = r + dr, nc = c + dc;\n    if ((dr || dc) && nr >= 0 && nr < R && nc >= 0 && nc < C) out.push(nr * C + nc);\n  }\n  return out;\n}\nfunction start() {\n  clearInterval(timer); started = false; over = false; opened = 0; flags = 0; secs = 0;\n  cells = Array.from({ length: R * C }, () => ({ mine: false, adj: 0, open: false, flag: false }));\n  const bd = $('bd'); bd.innerHTML = '';\n  cells.forEach((cell, i) => {\n    const b = document.createElement('button'); b.className = 'm'; cell.el = b; b.setAttribute('aria-label', 'Xana ' + (i + 1));\n    b.onclick = () => { if (lpFired) { lpFired = false; return; } flagMode ? toggle(i) : reveal(i); };\n    b.oncontextmenu = e => { e.preventDefault(); if (lpFired) return; toggle(i); };\n    let lp = null;\n    b.onpointerdown = e => { lpFired = false; if (e.pointerType !== 'mouse') lp = setTimeout(() => { lpFired = true; toggle(i); }, 420); };\n    const stop = () => { clearTimeout(lp); };\n    b.onpointerup = stop; b.onpointerleave = stop; b.onpointercancel = stop;\n    bd.appendChild(b);\n  });\n  $('msg').textContent = ''; $('left').textContent = MINES; $('tm').textContent = 0;\n}\nfunction plant(safe) {\n  const banned = new Set([safe, ...neighbors(safe)]);\n  let n = 0;\n  while (n < MINES) {\n    const i = Math.random() * R * C | 0;\n    if (!cells[i].mine && !banned.has(i)) { cells[i].mine = true; n++; }\n  }\n  cells.forEach((cell, i) => { cell.adj = neighbors(i).filter(j => cells[j].mine).length; });\n}\nfunction toggle(i) {\n  const cell = cells[i];\n  if (over || cell.open) return;\n  cell.flag = !cell.flag; flags += cell.flag ? 1 : -1;\n  cell.el.textContent = cell.flag ? '🚩' : ''; $('left').textContent = MINES - flags;\n}\nfunction show(i) {\n  const cell = cells[i], el = cell.el;\n  cell.open = true; opened++; el.classList.add('o');\n  el.textContent = cell.adj ? cell.adj : ''; if (cell.adj) el.classList.add('n' + cell.adj);\n}\nfunction reveal(i) {\n  if (over || cells[i].open || cells[i].flag) return;\n  if (!started) {\n    started = true; plant(i);\n    timer = setInterval(() => { secs++; $('tm').textContent = secs; }, 1000);\n  }\n  if (cells[i].mine) return lose(i);\n  const stack = [i];\n  while (stack.length) {\n    const k = stack.pop();\n    if (cells[k].open || cells[k].flag) continue;\n    show(k);\n    if (!cells[k].adj) neighbors(k).forEach(j => { if (!cells[j].open) stack.push(j); });\n  }\n  if (opened === R * C - MINES) {\n    over = true; clearInterval(timer); $('msg').textContent = 'Təbrik edirik! ' + secs + ' saniyəyə təmizlədin 🎉';\n    cells.forEach(cell => { if (cell.mine) cell.el.textContent = '🚩'; });\n  }\n}\nfunction lose(i) {\n  over = true; clearInterval(timer); $('msg').textContent = 'Mina partladı! 💥';\n  cells.forEach((cell, k) => {\n    if (cell.mine) { cell.el.textContent = '💣'; cell.el.classList.add('o'); }\n    if (k === i) cell.el.classList.add('x');\n  });\n}\n$('mode').onclick = () => {\n  flagMode = !flagMode; $('mode').classList.toggle('on', flagMode);\n  $('mode').textContent = '🚩 Bayraq rejimi: ' + (flagMode ? 'aktiv' : 'söndürülü');\n};\n$('re').onclick = start;\nstart();\n\n</script>\n</body>\n</html>\n";
